/* ============================================
   SKELETON COMPONENT
   Placeholder while content is loading
   ============================================ */

.ds-skeleton {
  background-color: var(--color-bg-container-secondary);
  position: relative;
  overflow: hidden;
}

.ds-skeleton::after {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: linear-gradient(
    90deg,
    transparent 0%,
    var(--color-bg-container-primary) 50%,
    transparent 100%
  );
  /* ds-allow(motion): the shimmer needs a symmetric in-out curve and no
     --motion-ease-* token provides one — the duration is tokenized. */
  animation: ds-skeleton-shimmer var(--motion-duration-loop-shimmer) ease-in-out infinite;
}

/* ============================================
   TEXT VARIANT
   ============================================ */

.ds-skeleton--text {
  height: 14px;
  border-radius: var(--radius-200);
  width: 100%;
}

/* ============================================
   CIRCULAR VARIANT
   ============================================ */

.ds-skeleton--circular {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-pill);
}

/* ============================================
   RECTANGULAR VARIANT
   ============================================ */

.ds-skeleton--rectangular {
  width: 100%;
  height: 100px;
  border-radius: var(--radius-200);
}

/* ============================================
   TEXT GROUP
   ============================================ */

.ds-skeleton__group {
  display: flex;
  flex-direction: column;
  gap: var(--padding-150);
}

/* ============================================
   SHIMMER ANIMATION
   ============================================ */

@keyframes ds-skeleton-shimmer {
  0% {
    transform: translateX(calc(-100% * var(--ds-inline-sign, 1)));
  }
  100% {
    transform: translateX(calc(100% * var(--ds-inline-sign, 1)));
  }
}

import React from 'react';
import './Skeleton.css';
import '../../behaviors/direction.css';

/** Props owned by Skeleton itself — everything else falls through to the root div. */
type SkeletonOwnProps = {
  /** Shape of the skeleton */
  variant?: 'text' | 'circular' | 'rectangular';
  /** Width (CSS value, e.g. '100%', '200px') */
  width?: string;
  /** Height (CSS value, e.g. '20px', '100px') */
  height?: string;
  /** Number of text lines to render (only for text variant) */
  lines?: number;
  /** Accessible name announced while the placeholder shows. A passed `aria-label` takes precedence. */
  loadingLabel?: string;
  /** Additional CSS classes. On a multi-line text skeleton they apply to each line, not the group. */
  className?: string;
};

export interface SkeletonProps
  extends SkeletonOwnProps,
    Omit<React.ComponentPropsWithoutRef<'div'>, keyof SkeletonOwnProps | 'children'> {}

/**
 * Skeleton displays a placeholder while content is loading.
 * Forwards a ref to the root div (the line group when `lines` is above one)
 * and spreads native attributes onto it.
 */
export const Skeleton = React.forwardRef<HTMLDivElement, SkeletonProps>(
  (
    {
      variant = 'text',
      width,
      height,
      lines = 1,
      loadingLabel = 'Loading',
      className = '',
      style,
      ...rest
    },
    ref,
  ) => {
    const baseClass = 'ds-skeleton';
    const classes = [baseClass, `${baseClass}--${variant}`, className]
      .filter(Boolean)
      .join(' ');

    if (variant === 'text' && lines > 1) {
      return (
        <div
          role="status"
          aria-label={loadingLabel}
          {...rest}
          ref={ref}
          className={`${baseClass}__group`}
          aria-busy="true"
          style={{ ...style, ...(width !== undefined && { width }) }}
        >
          {Array.from({ length: lines }).map((_, i) => (
            <div
              key={i}
              className={classes}
              aria-hidden="true"
              style={{
                width: i === lines - 1 ? '75%' : '100%',
                height,
              }}
            />
          ))}
        </div>
      );
    }

    return (
      <div
        role="status"
        aria-label={loadingLabel}
        {...rest}
        ref={ref}
        className={classes}
        aria-busy="true"
        style={{
          ...style,
          ...(width !== undefined && { width }),
          ...(height !== undefined && { height }),
        }}
      />
    );
  },
);

Skeleton.displayName = 'Skeleton';
